const PRECALC_QUESTIONS = [];
const PRECALC_UNIT_COUNTS = {};
function pq(unit, topicCode, topic, skill, calculatorAllowed, stem, correct, distractors, why, variantGroupId, stimulusGroupId, stimulus) {
  const number = (PRECALC_UNIT_COUNTS[unit] || 0) + 1;
  PRECALC_UNIT_COUNTS[unit] = number;
  const correctIndex = PRECALC_QUESTIONS.length % 4;
  const options = distractors.slice();
  options.splice(correctIndex, 0, correct);
  const explanation = why.length >= 90 ? why : `${why} This directly follows from the definitions and properties governing this topic.`;
  PRECALC_QUESTIONS.push({
    id: `apprecalc-${unit.toLowerCase()}-${String(number).padStart(3, "0")}`,
    unit, topicCode, topic, skill, calculatorAllowed, type: "s", q: stem, o: options, c: [correctIndex], e: explanation,
    variantGroupId, stimulusGroupId, stimulus,
  });
}

// --------------------------------------------------------------------------
// Unit 1: Polynomial and Rational Functions (14 topics)
// --------------------------------------------------------------------------
pq("U1","1.1","Change in Tandem","3",false,"Two quantities x and y are related so that y always increases whenever x increases, but the amount y increases is different for different increases in x. Which statement best describes this relationship?","y increases with x, but not always by the same amount.",["y changes at a constant rate with respect to x.","x is a function of y, but y is not a function of x.","y decreases whenever x increases."],"Change in tandem only requires that y consistently moves in one direction as x increases; it does not require the rate of change to be constant, which is a stronger, separate property.");
pq("U1","1.1","Change in Tandem","1",false,"A table shows x = 1, 2, 3, 4 paired with y = 2, 5, 10, 17. As x increases by 1 each time, how does the corresponding change in y behave?","The change in y grows larger each time.",["The change in y is constant at 3 each time.","The change in y decreases each time.","The change in y alternates between increasing and decreasing."],"The successive y-values 2, 5, 10, 17 have differences 3, 5, 7, which are themselves increasing, so y changes by a larger amount for each successive unit increase in x.");
pq("U1","1.1","Change in Tandem","2",true,"A tank's water level rises with time according to a table: at t = 0, 2, 4, 6 minutes, the depth is 10, 14, 19.6, 27.4 cm. Based on this table, is the depth changing at a constant rate with respect to time?","No, the depth's increase grows larger each interval.",["Yes, the depth increases by exactly 4.9 cm every 2 minutes.","No, the depth decreases over time.","Yes, the rate of change is exactly zero."],"The 2-minute changes are 4, 5.6, and 7.8 cm, which are increasing rather than constant, so depth and time are changing in tandem but not at a constant rate.");

pq("U1","1.2","Rates of Change","1",false,"For f(x) = x^2 + 1, what is the average rate of change of f over the interval [1, 4]?","5",["3","17","4"],"Average rate of change is [f(4) − f(1)]/(4 − 1) = (17 − 2)/3 = 15/3 = 5. This is a secant-line slope, not the function's slope at a single point, since f is not linear.");
pq("U1","1.2","Rates of Change","1",false,"For f(x) = x^3, what is the average rate of change of f over the interval [0, 2]?","4",["8","2","6"],"Average rate of change is [f(2) − f(0)]/(2 − 0) = (8 − 0)/2 = 4. Unlike a linear function, this ratio would give a different result over a different interval for this cubic.");
pq("U1","1.2","Rates of Change","2",true,"A company's revenue in thousands of dollars is R(t) = 3t^2 + 2t, where t is measured in years since 2020. What is the average rate of change of revenue from t = 2 to t = 5?","23 thousand dollars per year",["17 thousand dollars per year","85 thousand dollars per year","7 thousand dollars per year"],"Average rate of change is [R(5) − R(2)]/(5 − 2) = (85 − 16)/3 = 69/3 = 23 thousand dollars per year.");

pq("U1","1.3","Rates of Change in Linear and Quadratic Functions","3",false,"A table of a function's values shows that its first differences (successive changes in output) are constant. What type of function is the table most consistent with?","A linear function.",["A quadratic function.","An exponential function.","A rational function."],"A function has constant first differences over equally spaced inputs exactly when it changes at a constant rate, which is the defining property of a linear function.");
pq("U1","1.3","Rates of Change in Linear and Quadratic Functions","1",false,"For f(x) = 2x^2 − 3x + 1, evaluated at x = 0, 1, 2, 3, 4, what are the second differences of the resulting output values?","Constant at 4.",["Constant at 2.","Increasing: 2, 4, 6.","Constant at 0."],"The values are 1, 0, 3, 10, 21; the first differences are −1, 3, 7, 11; the second differences are 4, 4, 4 — constant, as expected for a quadratic with leading coefficient 2, since second differences equal 2a.");
pq("U1","1.3","Rates of Change in Linear and Quadratic Functions","3",false,"Unlike a linear function, the average rate of change of a quadratic function over consecutive equal-width intervals","changes by the same amount each interval.",["stays exactly the same from one interval to the next.","is always negative.","cannot be computed using the average rate of change formula."],"A quadratic's average rate of change over successive equal-width intervals forms an arithmetic sequence itself (increasing or decreasing by a constant amount), unlike a linear function's constant rate.");

pq("U1","1.4","Polynomial Functions and Rates of Change","1",true,"For g(x) = x^3 − 2x, what is the average rate of change of g over the interval [1, 3]?","11",["22","9","7"],"Average rate of change is [g(3) − g(1)]/(3 − 1) = (21 − (−1))/2 = 22/2 = 11. Note that g(1) = 1 − 2 = −1 is negative, which the subtraction in the numerator must account for correctly.");
pq("U1","1.4","Polynomial Functions and Rates of Change","3",false,"Near a zero of odd multiplicity 3, how does a polynomial's graph behave compared to near a zero of multiplicity 1?","It flattens and briefly levels off while crossing.",["It touches the x-axis without crossing it.","It behaves identically to a multiplicity-1 zero in every way.","It forms a sharp corner at the x-axis."],"Odd multiplicities greater than 1 still cross the x-axis, but higher odd multiplicities produce a flatter, S-shaped flexing near the zero rather than the more linear crossing seen at multiplicity 1.");
pq("U1","1.4","Polynomial Functions and Rates of Change","2",false,"On a graph of a degree-3 polynomial, the rate of change appears to slow down, momentarily flatten, then speed back up again as x increases through a certain interval. This behavior is most consistent with the graph passing near","a point of inflection.",["a vertical asymptote.","a hole in the graph.","an undefined point of the function."],"Polynomials are defined and smooth everywhere, so a momentary flattening of the rate of change (without the function stopping) is the signature of an inflection point, not an asymptote or discontinuity, which polynomials don't have.");

pq("U1","1.5","Polynomial Functions and Complex Zeros","1",false,"A degree-4 polynomial with real coefficients has zeros 2, −1, and 3 + 2i. What must its fourth zero be?","3 − 2i",["3 + 2i (a repeated zero)","−3 − 2i","2i"],"Non-real zeros of a polynomial with real coefficients occur in conjugate pairs, so if 3 + 2i is a zero, its conjugate 3 − 2i must also be a zero.");
pq("U1","1.5","Polynomial Functions and Complex Zeros","3",false,"Counting multiplicity, how many zeros (real and non-real) does a degree-5 polynomial with real coefficients have?","Exactly 5.",["At most 5, but possibly fewer.","Exactly 4, since one zero must be non-real.","At least 5, but possibly more."],"The Fundamental Theorem of Algebra guarantees a degree-n polynomial has exactly n zeros counting multiplicity, in the complex numbers, regardless of how many are real.");
pq("U1","1.5","Polynomial Functions and Complex Zeros","1",false,"A degree-3 polynomial with real coefficients has exactly one real zero at x = 5. What must be true of its other two zeros?","They are a pair of complex conjugates.",["They must also both be real.","They must both equal 5.","One is real and one is non-real."],"Non-real zeros always come in conjugate pairs for a polynomial with real coefficients, so if only one of the three zeros is real, the remaining two must be non-real conjugates of each other.");

pq("U1","1.6","Polynomial Functions and End Behavior","3",false,"For f(x) = −2x^3 + x − 1, what is the end behavior of f as x approaches positive and negative infinity?","As x → +∞, f(x) → −∞; as x → −∞, f(x) → +∞.",["As x → +∞, f(x) → +∞; as x → −∞, f(x) → +∞.","As x → +∞, f(x) → −∞; as x → −∞, f(x) → −∞.","As x → +∞, f(x) → +∞; as x → −∞, f(x) → −∞."],"For an odd-degree polynomial with a negative leading coefficient, the end behavior is opposite at the two ends: f(x) → −∞ as x → +∞ and f(x) → +∞ as x → −∞.");
pq("U1","1.6","Polynomial Functions and End Behavior","3",false,"For g(x) = 3x^4 − 5x^2 + 2, what is the end behavior of g as x approaches positive and negative infinity?","g(x) → +∞ at both ends.",["g(x) → −∞ at both ends.","g(x) → +∞ as x → +∞ and g(x) → −∞ as x → −∞.","g(x) → 0 at both ends."],"For an even-degree polynomial with a positive leading coefficient, both ends rise together: g(x) → +∞ as x → +∞ and also as x → −∞.");
pq("U1","1.6","Polynomial Functions and End Behavior","3",false,"Which feature of a polynomial's equation alone determines its end behavior?","The leading coefficient's sign and degree parity.",["The number of real zeros the polynomial has.","The y-intercept of the polynomial.","The presence of any repeated zeros."],"End behavior is governed entirely by the leading term, since it dominates all other terms for large |x|; that means only the leading coefficient's sign and whether the degree is even or odd matter.");

pq("U1","1.7","Rational Functions and End Behavior","1",false,"For f(x) = (3x^2 + 1)/(x^2 − 4), what is the horizontal asymptote?","y = 3",["y = 0","y = 1","There is no horizontal asymptote."],"When the numerator and denominator have the same degree, the horizontal asymptote is the ratio of their leading coefficients: 3/1 = 3.");
pq("U1","1.7","Rational Functions and End Behavior","1",false,"For g(x) = (2x + 1)/(x^2 − 1), what is the horizontal asymptote?","y = 0",["y = 2","y = 1","There is no horizontal asymptote."],"When the denominator's degree exceeds the numerator's degree, the function's value approaches 0 for large |x|, giving a horizontal asymptote of y = 0.");
pq("U1","1.7","Rational Functions and End Behavior","3",false,"For h(x) = (x^2 + 1)/(x − 1), what does the end behavior of h resemble for large |x|?","A slant line, since the degrees differ by 1.",["A horizontal line, since h has a horizontal asymptote.","A constant value, since h approaches a fixed limit.","No definable end behavior at all."],"When the numerator's degree is exactly one more than the denominator's, there's no horizontal asymptote; instead, the function approaches a slant asymptote found by polynomial division of the numerator by the denominator.");

pq("U1","1.8","Rational Functions and Zeros","1",false,"What are the zeros of f(x) = (x − 3)(x + 2)/(x − 5)?","x = 3 and x = −2",["x = 5","x = 3, x = −2, and x = 5","x = −3 and x = 2"],"A rational function's zeros are the x-values that make the numerator zero, provided they don't also make the denominator zero; here x = 3 and x = −2 zero the numerator, and neither equals 5.");
pq("U1","1.8","Rational Functions and Zeros","3",false,"For g(x) = (x − 4)(x + 1)/(x − 4), is x = 4 a zero of g?","No, x = 4 also zeroes the denominator there.",["Yes, since x = 4 makes the numerator zero.","Yes, because g(4) equals infinity, which counts as a zero.","No, because x = 4 makes the function positive."],"An x-value only counts as a zero if the function is actually defined and equal to 0 there. Since x = 4 makes both the numerator and denominator zero, it's a removable discontinuity (a hole), not a zero of g.");
pq("U1","1.8","Rational Functions and Zeros","1",true,"What are the zeros of the rational function r(x) = (2x − 6)(x + 5)/(x^2 + 1)?","x = 3 and x = −5",["x = −3 and x = 5","x = 3 only, treating x^2 + 1 as never contributing a real zero","x = −5, the other real-looking candidate"],"Setting the numerator to zero: 2x − 6 = 0 gives x = 3, and x + 5 = 0 gives x = −5. The denominator x^2 + 1 is never zero for real x, so both values are valid zeros.");

pq("U1","1.9","Rational Functions and Vertical Asymptotes","1",false,"What are the vertical asymptotes of f(x) = (x + 1)/[(x − 2)(x + 5)]?","x = 2 and x = −5",["x = −1 only","x = 2, x = −5, and x = −1","x = −1, x = 2, and x = 5"],"Vertical asymptotes occur where the denominator is zero and the numerator is not simultaneously zero. Here (x − 2)(x + 5) = 0 gives x = 2 and x = −5, and neither makes the numerator x + 1 equal to zero.");
pq("U1","1.9","Rational Functions and Vertical Asymptotes","3",false,"A rational function has a factor of (x − 3) in both its numerator and denominator, and no other shared factors. What happens at x = 3?","There is a hole at x = 3, not an asymptote there.",["There is a vertical asymptote at x = 3.","The function has a zero at x = 3.","The function is undefined everywhere, not just at x = 3."],"When a factor cancels between numerator and denominator, the discontinuity at that x-value becomes removable (a hole) rather than a vertical asymptote, since the surrounding behavior no longer blows up to infinity.");
pq("U1","1.9","Rational Functions and Vertical Asymptotes","1",true,"For g(x) = (x + 4)/(x^2 − 9), what are the vertical asymptotes?","x = 3 and x = −3",["x = −4 only","x = 3, x = −3, and x = −4","x = 9 and x = −9"],"The denominator x^2 − 9 factors as (x − 3)(x + 3), giving zeros at x = 3 and x = −3. Neither value makes the numerator x + 4 equal to zero, so both are vertical asymptotes.");

pq("U1","1.10","Rational Functions and Holes","1",false,"For f(x) = (x^2 − 9)/(x − 3), what is the location and value of the hole in its graph?","A hole at x = 3, with simplified value 6.",["A vertical asymptote at x = 3.","A hole at x = −3, where the value would be −6.","No hole exists; the function is defined at x = 3."],"Factoring gives f(x) = (x − 3)(x + 3)/(x − 3), which simplifies to x + 3 for x ≠ 3. The hole sits at x = 3, and the simplified expression gives a y-value of 3 + 3 = 6 there.");
pq("U1","1.10","Rational Functions and Holes","1",true,"For g(x) = (x^2 + x − 6)/(x − 2), where is the hole in the graph located?","At x = 2, where the simplified function equals 5.",["At x = −3, where the simplified function equals 0.","At x = 2, where the simplified function equals 0.","There is no hole; x = 2 is a vertical asymptote."],"Factoring the numerator gives (x − 2)(x + 3), so g(x) = (x − 2)(x + 3)/(x − 2) simplifies to x + 3 for x ≠ 2. The hole is at x = 2, with simplified value 2 + 3 = 5.");
pq("U1","1.10","Rational Functions and Holes","3",false,"How can you tell, before graphing, whether a rational function will have a hole rather than a vertical asymptote at a given x-value?","Check whether that factor also zeroes the numerator.",["Check whether the x-value is positive or negative.","Check whether the function's degree is even or odd.","Holes cannot be determined algebraically; only a graph reveals them."],"A hole occurs exactly where a common factor cancels between numerator and denominator, so testing whether that factor also zeroes the numerator at the same x-value tells you whether it's a hole (cancels) or a vertical asymptote (doesn't cancel) without graphing.");

pq("U1","1.11","Equivalent Representations of Polynomial and Rational Expressions","1",false,"What is the quotient when x^3 − 2x^2 + x − 2 is divided by x − 2?","x^2 + 1",["x^2 − 1","x^2 + 2x + 1","x^2 + x + 1"],"Synthetic division of 1, −2, 1, −2 by root 2 gives coefficients 1, 0, 1 with remainder 0, so the quotient is x^2 + 0x + 1 = x^2 + 1, and the division is exact.");
pq("U1","1.11","Equivalent Representations of Polynomial and Rational Expressions","1",false,"Which expression is equivalent to (x^2 − 5x + 6)/(x − 3) for x ≠ 3?","x − 2",["x + 2","x − 3","x^2 − 2"],"Factoring the numerator gives (x − 3)(x − 2), so dividing by (x − 3) leaves x − 2 for all x ≠ 3.");
pq("U1","1.11","Equivalent Representations of Polynomial and Rational Expressions","3",false,"Rewriting a rational expression in an equivalent factored or divided form is most useful for","revealing zeros, holes, and asymptotes not obvious otherwise.",["changing the actual output values of the function at any input.","making the function defined at values where it was previously undefined.","converting the function from rational to polynomial no matter what."],"Equivalent algebraic forms represent the same function and don't change its values, but a factored or divided form can make key features like zeros, holes, and asymptotes far easier to identify directly from the expression.");

pq("U1","1.12","Transformations of Functions","1",false,"If g(x) = f(x − 2) + 3, how is the graph of g related to the graph of f?","Shifted right 2 units and up 3 units.",["Shifted left 2 units and down 3 units.","Shifted right 2 units and down 3 units.","Shifted left 2 units and up 3 units."],"Replacing x with x − 2 inside f shifts the graph right 2 units, and adding 3 outside f shifts the entire graph up 3 units.");
pq("U1","1.12","Transformations of Functions","1",false,"If h(x) = 3f(x), how does the graph of h compare to the graph of f?","Every output is stretched vertically by a factor of 3.",["Every output value is compressed vertically by a factor of 3.","The graph is shifted 3 units up.","The graph is stretched horizontally by a factor of 3."],"Multiplying the entire function by 3 multiplies every output (y-value) by 3, which is a vertical stretch by a factor of 3, leaving the x-values (horizontal position) unchanged.");
pq("U1","1.12","Transformations of Functions","1",true,"If k(x) = f(2x), how does the graph of k compare to the graph of f?","Compressed horizontally by a factor of 2.",["Stretched horizontally by a factor of 2.","Stretched vertically by a factor of 2.","Shifted left by 2 units."],"Replacing x with 2x inside f causes inputs to reach any given output twice as fast, which compresses the graph horizontally by a factor of 2 (each x-coordinate is divided by 2).");

pq("U1","1.13","Function Model Selection and Assumption Articulation","3",false,"A data table shows that the second differences of the outputs (for equally spaced inputs) are constant and nonzero. Which type of function model is most appropriate?","A quadratic function.",["A linear function.","An exponential function.","A logarithmic function."],"Constant, nonzero second differences over equally spaced inputs are the defining numerical signature of a quadratic function, distinguishing it from linear (constant first differences) or exponential (constant ratios) behavior.");
pq("U1","1.13","Function Model Selection and Assumption Articulation","3",false,"When a polynomial model is used to predict values far outside the range of the original data, which assumption is being made, and why might it be risky?","That the same pattern holds outside the observed data.",["That the model is exact and requires essentially no assumptions.","That extrapolation is mathematically forbidden in general.","That the data must have been collected using a calculator."],"Extrapolating a polynomial model assumes the underlying relationship continues unchanged beyond the observed range, but many real phenomena change behavior (level off, reverse, or become undefined) outside the range where the data was actually collected.");
pq("U1","1.13","Function Model Selection and Assumption Articulation","3",false,"A data set's outputs grow by roughly the same constant amount for every equal increase in input. Which model assumption is best supported by this pattern?","A linear model, assuming the constant rate persists.",["A quadratic model, assuming the second differences are constant.","An exponential model, assuming a constant percentage growth rate.","No model can be justified from this pattern alone."],"Constant first differences over equal input increases are the hallmark of a linear relationship, so a linear model — under the assumption that this constant rate persists — is the best-supported choice here.");

pq("U1","1.14","Function Model Construction and Application","1",true,"A quadratic model has vertex (2, 5) and passes through the point (0, 1). What is the value of this model at x = 4?","1",["5","9","−3"],"Using vertex form f(x) = a(x − 2)^2 + 5 and the point (0,1): 1 = a(0−2)^2 + 5 = 4a + 5, so a = −1. Then f(4) = −1(4−2)^2 + 5 = −4 + 5 = 1.");
pq("U1","1.14","Function Model Construction and Application","1",true,"A cubic model is built so that f(0) = 2 and f(x) increases by exactly 12 units total from x = 0 to x = 2, with a constant average rate of change over that interval. What is f(2)?","14",["10","24","16"],"An average rate of change describes total change divided by interval width, so if f changes by a total of 12 over the interval, f(2) = f(0) + 12 = 2 + 12 = 14, regardless of whether the actual rate is literally constant point-to-point.");
pq("U1","1.14","Function Model Construction and Application","3",false,"After constructing a function model from a data set, which step is essential before using the model to make a prediction?","Verifying the model fits the data reasonably well.",["Immediately using the model for any prediction, regardless of input value.","Discarding the original data once the model equation is found.","Ensuring the model has the highest possible degree."],"A constructed model is only as trustworthy as its fit to the real data and the reasonableness of extrapolating to a given input; skipping this check risks using a mathematically valid but practically meaningless prediction.");

// --------------------------------------------------------------------------
// Unit 2: Exponential and Logarithmic Functions (15 topics)
// --------------------------------------------------------------------------
pq("U2","2.1","Change in Arithmetic and Geometric Sequences","1",false,"An arithmetic sequence has first term 5 and common difference 3. What is the 4th term?","14",["12","54","17"],"For an arithmetic sequence, each term adds the common difference: a4 = a1 + 3d = 5 + 3(3) = 5 + 9 = 14.");
pq("U2","2.1","Change in Arithmetic and Geometric Sequences","1",false,"A geometric sequence has first term 2 and common ratio 3. What is the 4th term?","54",["24","18","6"],"For a geometric sequence, each term multiplies by the common ratio: a4 = a1 · r^3 = 2 · 3^3 = 2 · 27 = 54.");
pq("U2","2.1","Change in Arithmetic and Geometric Sequences","3",false,"What is the key structural difference between how an arithmetic sequence changes and how a geometric sequence changes?","Arithmetic sequences add a constant amount; geometric sequences multiply by a constant ratio.",["An arithmetic sequence multiplies by a constant ratio, while a geometric sequence adds a constant amount.","Both sequences change by adding the same constant amount between terms.","Both sequences change by multiplying by the same constant ratio between terms."],"By definition, arithmetic sequences have constant additive differences between consecutive terms, while geometric sequences have constant multiplicative ratios between consecutive terms — the discrete analogs of linear and exponential change.");

pq("U2","2.2","Change in Linear and Exponential Functions","1",false,"A table shows x = 0, 1, 2, 3 paired with y = 5, 10, 20, 40. What type of function best models this data?","An exponential function, given the constant ratio of 2.",["A linear function, since consecutive y-values share a constant difference.","A quadratic function, since the second differences are constant.","No standard function type fits this pattern."],"The ratios 10/5, 20/10, and 40/20 are all equal to 2, a constant ratio between consecutive outputs for equally spaced inputs, which is the defining signature of exponential growth.");
pq("U2","2.2","Change in Linear and Exponential Functions","3",false,"A linear function and an exponential function both pass through the same two points, with the exponential function currently growing. For inputs far beyond those two points, which function's outputs eventually become larger?","The exponential function's outputs eventually exceed the linear function's.",["The linear function's outputs eventually exceed the exponential function's.","The two functions' outputs remain equal forever beyond those two points.","It is impossible to determine without more specific information."],"Because exponential growth compounds multiplicatively while linear growth only adds a constant amount per step, any increasing exponential function eventually outgrows any linear function, regardless of the linear function's rate.");
pq("U2","2.2","Change in Linear and Exponential Functions","1",true,"A quantity changes from 40 to 65 as x goes from 0 to 5, decreasing evenly for a linear model. What is the constant rate of change of this linear model?","5 per unit of x",["25 per unit of x","8 per unit of x","−5 per unit of x"],"The rate of change is (65 − 40)/(5 − 0) = 25/5 = 5 per unit of x — a positive rate, since the quantity increased from 40 to 65.");

pq("U2","2.3","Exponential Functions","1",false,"For f(x) = 3 · 2^x, what is f(3)?","24",["9","18","48"],"f(3) = 3 · 2^3 = 3 · 8 = 24. The coefficient 3 multiplies the entire power 2^3, rather than being combined with the base before exponentiating.");
pq("U2","2.3","Exponential Functions","1",false,"Which condition must the base b of an exponential function f(x) = a · b^x satisfy for f to represent exponential decay (with a > 0)?","0 < b < 1",["b > 1","b < 0","b = 1"],"For a > 0, the function decreases as x increases exactly when the base b is between 0 and 1, since each unit increase in x multiplies the output by a factor less than 1.");
pq("U2","2.3","Exponential Functions","3",false,"For an exponential function f(x) = a · b^x with a > 0 and b > 1, what happens to the output every time the input increases by exactly 1?","The output is multiplied by the fixed factor b.",["The output increases by the fixed amount a.","The output is multiplied by the fixed factor a.","The output increases by a different amount each time, with no fixed pattern."],"By definition, each unit increase in x multiplies the current output by the base b, since f(x+1) = a·b^(x+1) = b·(a·b^x) = b·f(x); this constant multiplicative factor is the defining feature of exponential change.");

pq("U2","2.4","Exponential Function Manipulation","1",false,"Which expression is equivalent to 2^(x+3)?","8 · 2^x",["2^x + 8","6 · 2^x","2^(3x)"],"Using the product rule for exponents, 2^(x+3) = 2^x · 2^3 = 2^x · 8 = 8 · 2^x. Adding exponents in the original expression corresponds to multiplying the separated factors.");
pq("U2","2.4","Exponential Function Manipulation","1",false,"An exponential function is written as f(x) = 100(1.05)^x. What is the growth factor applied each time x increases by 1, and what percent growth rate does this represent?","A growth factor of 1.05, representing 5% growth per unit increase in x.",["A growth factor of 0.05, representing 5% growth per unit increase in x.","A growth factor of 1.05, representing 105% growth per unit increase in x.","A growth factor of 105, representing 105% growth per unit increase in x."],"The base 1.05 is the multiplicative growth factor applied each unit step, and since 1.05 = 1 + 0.05, this corresponds to a 5% increase per step, not 105%.");
pq("U2","2.4","Exponential Function Manipulation","1",true,"Which expression is equivalent to (4^x)^2 / 4^x for x ≠ 0?","4^x",["4^(2x)","4^(x^2)","16^x"],"(4^x)^2 = 4^(2x), so (4^x)^2/4^x = 4^(2x)/4^x = 4^(2x−x) = 4^x by the quotient rule for exponents.");

pq("U2","2.5","Exponential Function Context and Data Modeling","1",true,"A population is modeled by P(t) = 500(1.03)^t, where t is years since a baseline year. What does this model predict for the population after 10 years, rounded to the nearest whole number?","672",["515","1000","550"],"P(10) = 500(1.03)^10 ≈ 500(1.34392) ≈ 671.96, which rounds to 672. Each year multiplies the population by 1.03 rather than adding a fixed amount, which is why the growth compounds.");
pq("U2","2.5","Exponential Function Context and Data Modeling","3",false,"In the exponential model P(t) = P0 · b^t for a population, what does the value of P0 represent in context?","The population at time t = 0.",["The percent growth rate of the population.","The population after 1 unit of time has passed.","The maximum possible population the model allows."],"Setting t = 0 in P(t) = P0 · b^t gives P(0) = P0 · b^0 = P0, so P0 is exactly the initial value of the modeled quantity at the starting time.");
pq("U2","2.5","Exponential Function Context and Data Modeling","1",true,"A radioactive sample decays according to A(t) = 80(0.5)^(t/3), where t is in years. What is the amount remaining after 6 years?","20",["40","10","60"],"A(6) = 80(0.5)^(6/3) = 80(0.5)^2 = 80(0.25) = 20. Six years is exactly two 3-year half-lives, so the original amount is halved twice: 80 → 40 → 20.");

pq("U2","2.6","Competing Function Model Validation","3",false,"Two models are fit to the same data set over the observed range: a linear model and an exponential model, both with similar residuals. Which additional check best helps decide which model is more appropriate going forward?","Testing predictions against new data outside the range.",["Choosing the model with the higher degree automatically.","Choosing whichever model was easier to compute.","Assuming the exponential model is always correct for growth data."],"Since both models fit the observed data comparably, the strongest test of which one actually captures the underlying pattern is checking their predictive accuracy on data the models were not fit to.");
pq("U2","2.6","Competing Function Model Validation","3",false,"A data set shows outputs that are always positive and appear to have a roughly constant ratio between consecutive equally spaced values. Which model should be rejected as a poor fit based on this pattern alone?","A linear model, since constant ratios signal exponential, not linear, behavior.",["An exponential model, since constant ratios are inconsistent with exponential behavior.","Both a linear and an exponential model, since neither can ever produce constant ratios.","Neither model can be evaluated without more information."],"A roughly constant ratio between consecutive equally spaced outputs is the hallmark of exponential behavior, not linear behavior (which instead shows constant differences), so a linear model would be the poorer fit here.");

pq("U2","2.7","Composition of Functions","1",false,"For f(x) = x^2 and g(x) = x + 1, what is f(g(2))?","9",["5","4","3"],"First evaluate g(2) = 2 + 1 = 3, then f(3) = 3^2 = 9. Composition applies the inner function first, so g is evaluated before its output is passed into f.");
pq("U2","2.7","Composition of Functions","1",false,"For f(x) = x^2 and g(x) = x + 1, what is g(f(2))?","5",["9","4","3"],"First evaluate f(2) = 2^2 = 4, then g(4) = 4 + 1 = 5. Reversing the order of composition from the previous problem changes which function is applied first, and gives a different result.");
pq("U2","2.7","Composition of Functions","3",false,"For the functions in the previous two problems, why do f(g(2)) and g(f(2)) give different results?","Composition generally isn't commutative, so a different order can give a different result.",["One of the two functions must have been evaluated incorrectly.","f and g must not actually be valid functions.","Composition always gives the same result regardless of order, so this indicates an error."],"Unlike multiplication of numbers, composing functions in a different order — f(g(x)) versus g(f(x)) — is a fundamentally different operation and generally produces different results unless the specific functions happen to commute.");

pq("U2","2.8","Inverse Functions","1",false,"For f(x) = 3x − 2, what is f⁻¹(x)?","(x + 2)/3",["(x − 2)/3","3x + 2","(2 − x)/3"],"Solving y = 3x − 2 for x gives x = (y + 2)/3, so swapping variable roles gives f⁻¹(x) = (x + 2)/3.");
pq("U2","2.8","Inverse Functions","3",false,"For a function to have an inverse that is also a function, what property must the original function have?","It must be one-to-one.",["It must be increasing everywhere.","It must be a polynomial.","It must pass through the origin."],"An inverse relation only qualifies as a function itself when the original function is one-to-one, since otherwise some output value would need to map back to more than one input, violating the definition of a function.");
pq("U2","2.8","Inverse Functions","1",true,"If f(x) = 2x + 5 and f⁻¹ is its inverse, what is f⁻¹(f(7))?","7",["19","2.5","9"],"By the defining property of inverse functions, f⁻¹(f(x)) = x for every x in the domain, so f⁻¹(f(7)) = 7 without needing to compute f(7) directly.");

pq("U2","2.9","Logarithmic Expressions","1",false,"What is the exact value of log2(8)?","3",["4","2","8"],"log2(8) asks: 2 raised to what power equals 8? Since 2^3 = 8, log2(8) = 3. A logarithm is fundamentally a question about an unknown exponent, not a separate operation unrelated to exponentiation.");
pq("U2","2.9","Logarithmic Expressions","1",false,"What is the exact value of log3(1/9)?","−2",["2","−3","1/2"],"log3(1/9) asks: 3 raised to what power equals 1/9? Since 3^(−2) = 1/9, log3(1/9) = −2. A negative exponent is expected here, since the base 3 must be raised to a negative power to produce a value less than 1.");
pq("U2","2.9","Logarithmic Expressions","1",false,"What is the exact value of log5(1)?","0",["1","5","undefined"],"Any nonzero base raised to the power 0 equals 1, so log5(1) = 0 for the same reason log_b(1) = 0 for any valid base b.");

pq("U2","2.10","Inverses of Exponential Functions","1",false,"What function is the inverse of f(x) = 2^x?","f⁻¹(x) = log2(x)",["f⁻¹(x) = x^2","f⁻¹(x) = (1/2)^x","f⁻¹(x) = 2^(1/x)"],"The logarithm is defined precisely as the inverse operation of exponentiation with the same base, so the inverse of f(x) = 2^x is f⁻¹(x) = log2(x).");
pq("U2","2.10","Inverses of Exponential Functions","3",false,"Why must the domain of log2(x) be restricted to x > 0?","Because 2^x is always positive.",["Because logarithms are only defined for whole numbers.","Because 2^x is undefined for negative or zero inputs.","Because negative logarithm values are not allowed."],"The domain of an inverse function equals the range of the original function; since 2^x > 0 for every real x, the range of 2^x is all positive numbers, which becomes the required domain restriction x > 0 for log2(x).");
pq("U2","2.10","Inverses of Exponential Functions","1",true,"If f(x) = 5^x, what is f⁻¹(125)?","3",["25","5","625"],"f⁻¹(125) asks for the exponent x such that 5^x = 125. Since 5^3 = 125, f⁻¹(125) = 3. Because f is exponential, its inverse is logarithmic, so evaluating f⁻¹ at a value is equivalent to asking what power produced that value.");

pq("U2","2.11","Logarithmic Functions","1",false,"What is the exact value of log10(100)?","2",["10","100","1"],"log10(100) asks: 10 raised to what power equals 100? Since 10^2 = 100, log10(100) = 2. This is the same reasoning used for any base-10 logarithm of a power of 10.");
pq("U2","2.11","Logarithmic Functions","1",false,"What is ln(e^3), where ln denotes the natural logarithm (base e)?","3",["e^3","1","e"],"Because the natural logarithm is the inverse of the exponential function with base e, ln(e^3) simply returns the exponent: 3.");
pq("U2","2.11","Logarithmic Functions","3",false,"As x approaches 0 from the positive side, what happens to the value of f(x) = log2(x)?","f(x) decreases steadily.",["f(x) approaches 0.","f(x) approaches positive infinity.","f(x) approaches 1."],"A logarithmic function has a vertical asymptote at x = 0; as x shrinks toward 0 from the positive side, the exponent needed to produce such a small positive number from the base becomes an increasingly large negative number.");

pq("U2","2.12","Logarithmic Function Manipulation","1",false,"Using the product property of logarithms, what is log2(8) + log2(4) equal to?","log2(32)",["log2(12)","log2(2)","log2(4)"],"The product property states log_b(m) + log_b(n) = log_b(mn), so log2(8) + log2(4) = log2(8·4) = log2(32); numerically this checks out as 3 + 2 = 5 = log2(32).");
pq("U2","2.12","Logarithmic Function Manipulation","1",false,"Which expression is equivalent to 2·log2(3)?","log2(9)",["log2(6)","log2(3) + 2","4·log2(3)"],"The power property states k·log_b(m) = log_b(m^k), so 2·log2(3) = log2(3^2) = log2(9). Numerically this checks out: 2·log2(3) ≈ 2(1.585) ≈ 3.17, matching log2(9) ≈ 3.17.");
pq("U2","2.12","Logarithmic Function Manipulation","1",true,"Which expression is equivalent to log(20) − log(4), using the quotient property of logarithms?","log(5)",["log(16)","log(80)","log(24)"],"The quotient property states log_b(m) − log_b(n) = log_b(m/n), so log(20) − log(4) = log(20/4) = log(5).");

pq("U2","2.13","Exponential and Logarithmic Equations and Inequalities","1",false,"Solve for x: 2^x = 32.","x = 5",["x = 16","x = 6","x = 4"],"Rewriting 32 as a power of 2 gives 2^5 = 32, and since the bases match, x = 5. Matching bases on both sides of an exponential equation lets the exponents be compared directly.");
pq("U2","2.13","Exponential and Logarithmic Equations and Inequalities","1",false,"Solve for x: log2(x) = 4.","x = 16",["x = 8","x = 2","x = 4"],"By the definition of logarithm, log2(x) = 4 means 2^4 = x, so x = 16. Converting a logarithmic equation into its equivalent exponential form is often the fastest way to solve for an unknown inside the logarithm.");
pq("U2","2.13","Exponential and Logarithmic Equations and Inequalities","1",true,"Solve for x: 3 · 2^x = 96.","x = 5",["x = 32","x = 4","x = 6"],"Dividing both sides by 3 gives 2^x = 32, and since 2^5 = 32, x = 5. Isolating the exponential term before rewriting both sides with a common base is a standard first step for this equation type.");

pq("U2","2.14","Logarithmic Function Context and Data Modeling","3",false,"The Richter scale for earthquake magnitude is defined using a base-10 logarithm of wave amplitude. What is the practical effect of using a logarithmic rather than a linear scale for this measurement?","It compresses a huge amplitude range into manageable numbers.",["It makes every earthquake appear to have exactly the same measured amplitude.","It converts the amplitude data into an exponential rather than logarithmic pattern.","It has no practical effect compared to a linear scale."],"Logarithmic scales are chosen specifically when raw values span many orders of magnitude, since taking a logarithm compresses that vast range into a much narrower, easier-to-communicate span of numbers.");
pq("U2","2.14","Logarithmic Function Context and Data Modeling","1",true,"The pH of a solution is defined as pH = −log10[H+], where [H+] is hydrogen ion concentration in mol/L. If a solution has [H+] = 10^(−3) mol/L, what is its pH?","3",["−3","10","1000"],"pH = −log10(10^(−3)) = −(−3) = 3. The negative sign in the pH formula is what turns a negative exponent (from a very small concentration) into a positive, easily readable pH value.");
pq("U2","2.14","Logarithmic Function Context and Data Modeling","3",false,"A sound intensity model uses decibels, defined with a logarithmic formula, rather than reporting raw sound intensity directly. What real-world property of human hearing does this logarithmic definition reflect?","Perceived loudness tracks the logarithm of intensity, not raw intensity.",["Human hearing can detect sounds only below a certain fixed volume.","Sound intensity itself happens to be measured in whole numbers.","Logarithmic units make the measured values larger for easier reading."],"Decibel scales are logarithmic because human perception of loudness is roughly proportional to the logarithm of the actual physical sound intensity, not the raw intensity value, so the logarithmic scale better matches perceived loudness.");

pq("U2","2.15","Semi-log Plots","3",false,"A set of data is plotted with a semi-log plot (input on a regular axis, output on a logarithmic axis), and the resulting graph appears as a straight line. What does this indicate about the underlying data?","The data fits an exponential model best.",["The data is well modeled by a linear function in its original form.","The data cannot be modeled by any standard function type.","The data must be periodic."],"If y = A·B^x, then log(y) = log(A) + x·log(B), which is linear in x; this is exactly why a semi-log plot straightens out exponential data — the log-axis transformation turns exponential curvature into a straight line.");
pq("U2","2.15","Semi-log Plots","1",true,"For y = 5 · 2^x, what is log10(y) when x = 3?","About 1.602",["About 0.699","About 40","About 1.204"],"log10(5·2^3) = log10(40) ≈ 1.602, consistent with the general form log10(y) = log10(5) + x·log10(2) ≈ 0.699 + 3(0.301) ≈ 1.602.");
pq("U2","2.15","Semi-log Plots","3",false,"On a semi-log plot of an exponential function y = A·B^x, what does the slope of the resulting straight line represent?","The base-10 logarithm of the growth factor B.",["The initial value A directly.","The growth factor B directly.","The value of x where y first becomes positive."],"Since log10(y) = log10(A) + x·log10(B) is linear in x with slope log10(B), the visible slope on a semi-log plot directly reveals the logarithm of the exponential function's growth factor, not the factor or initial value themselves.");

// --------------------------------------------------------------------------
// Unit 3: Trigonometric and Polar Functions (15 topics)
// --------------------------------------------------------------------------
pq("U3","3.1","Periodic Phenomena","3",false,"A quantity repeats the same pattern of values over and over at regular intervals as its input increases. What term describes this behavior, and what is the length of one repeating interval called?","Periodic behavior; the length of one repeating interval is called the period.",["Periodic behavior; the length of one repeating interval is called the amplitude.","Symmetric behavior; the length of one repeating interval is called the frequency.","Cyclical decay; the length of one repeating interval is called the midline."],"A function is periodic when its values repeat in a regular pattern; the smallest interval over which the entire pattern repeats is defined as the period, distinct from amplitude (the size of the swing) or midline (the center value).");
pq("U3","3.1","Periodic Phenomena","3",false,"Which of the following real-world quantities is best modeled as a periodic function of time?","The height of a specific point on a rotating Ferris wheel.",["The total distance a car has traveled since starting a trip.","The balance of a savings account earning compound interest.","The population of a city that is steadily increasing each year."],"A point on a rotating wheel returns to the same height after each full rotation, repeating the same pattern indefinitely, which is the defining property of periodic behavior — unlike total distance, account balance, or population, which don't repeat.");

pq("U3","3.2","Sine, Cosine, and Tangent","1",false,"What is the exact value of sin(π/6)?","1/2",["√2/2","√3/2","1"],"π/6 (30°) is a standard reference angle where sin(π/6) = 1/2, a value that should be memorized as part of the standard unit circle values.");
pq("U3","3.2","Sine, Cosine, and Tangent","1",false,"What is the exact value of cos(π/3)?","1/2",["√3/2","√2/2","0"],"π/3 (60°) is a standard reference angle where cos(π/3) = 1/2, part of the standard set of unit circle values.");
pq("U3","3.2","Sine, Cosine, and Tangent","1",false,"What is the exact value of tan(π/3)?","√3",["1/√3","1","√3/2"],"tan(π/3) = sin(π/3)/cos(π/3) = (√3/2)/(1/2) = √3, consistent with the standard unit circle values at this reference angle.");

pq("U3","3.3","Sine and Cosine Function Values","1",false,"What is the exact value of sin(2π/3)?","√3/2",["−√3/2","1/2","−1/2"],"2π/3 is in the second quadrant, where sine is positive. Its reference angle is π/3, so sin(2π/3) = sin(π/3) = √3/2.");
pq("U3","3.3","Sine and Cosine Function Values","1",false,"What is the exact value of cos(5π/6)?","−√3/2",["√3/2","−1/2","1/2"],"5π/6 is in the second quadrant, where cosine is negative. Its reference angle is π/6, so cos(5π/6) = −cos(π/6) = −√3/2.");
pq("U3","3.3","Sine and Cosine Function Values","3",false,"For an angle in the third quadrant, what are the signs of sine and cosine?","Both sine and cosine are negative.",["Sine is positive and cosine is negative.","Sine is negative and cosine is positive.","Both sine and cosine are positive."],"In the third quadrant, both the x-coordinate (cosine) and y-coordinate (sine) of a point on the unit circle are negative, so both trigonometric values are negative there.");

pq("U3","3.4","Sine and Cosine Function Graphs","3",false,"On the graph of y = sin(x), at which x-value in [0, 2π) does the function first reach its maximum value?","x = π/2",["x = π","x = 0","x = 3π/2"],"The graph of y = sin(x) rises from 0 at x = 0 to its maximum value of 1 at x = π/2, the first point where the sine curve peaks in that interval.");
pq("U3","3.4","Sine and Cosine Function Graphs","3",false,"How does the graph of y = cos(x) relate to the graph of y = sin(x)?","The cosine graph is the sine graph shifted left by π/2.",["The cosine graph is the sine graph shifted right by π.","The cosine graph is the sine graph reflected over the x-axis.","The cosine and sine graphs are unrelated to each other by any transformation."],"Since cos(x) = sin(x + π/2), the graph of cosine is exactly the sine graph shifted π/2 units to the left, both being the same wave shape offset from one another.");

pq("U3","3.5","Sinusoidal Functions","1",false,"For f(x) = 3sin(2x) + 1, what are the amplitude and midline of this function?","Amplitude 3, midline y = 1.",["Amplitude 1, midline y = 3.","Amplitude 2, midline y = 3.","Amplitude 3, midline y = 2."],"In the form a·sin(bx) + k, the amplitude is |a| = 3 and the midline is y = k = 1; the coefficient b affects only the period, not the amplitude or midline.");
pq("U3","3.5","Sinusoidal Functions","1",false,"For g(x) = 4cos(x) + 2, what are the maximum and minimum values of g?","Maximum 6, minimum −2.",["Maximum 4, minimum 2.","Maximum 6, minimum 2.","Maximum 4, minimum −4."],"With amplitude 4 and midline y = 2, the function swings from 2 − 4 = −2 up to 2 + 4 = 6, giving a minimum of −2 and maximum of 6.");
pq("U3","3.5","Sinusoidal Functions","1",false,"For h(x) = sin(2x), what is the period of h?","π",["2π","4π","π/2"],"For a sinusoidal function with argument bx, the period is 2π/|b| = 2π/2 = π. Doubling the coefficient of x compresses the graph horizontally, completing one full cycle in half the usual distance.");

pq("U3","3.6","Sinusoidal Function Transformations","1",false,"How does the graph of g(x) = sin(x − π/4) relate to the graph of f(x) = sin(x)?","Shifted right by π/4.",["Shifted left by π/4.","Shifted up by π/4.","Compressed horizontally by π/4."],"Replacing x with x − π/4 inside the sine function shifts the entire graph to the right by π/4, a horizontal (phase) shift.");
pq("U3","3.6","Sinusoidal Function Transformations","1",false,"Which transformation converts f(x) = sin(x) into g(x) = 2sin(x) − 3?","A vertical stretch by a factor of 2, followed by a shift down 3 units.",["A horizontal stretch by a factor of 2, followed by a shift down 3 units.","A vertical stretch by a factor of 2, followed by a shift up 3 units.","A vertical compression by a factor of 2, followed by a shift down 3 units."],"Multiplying the output by 2 stretches the graph vertically by a factor of 2 (doubling the amplitude), and subtracting 3 afterward shifts the entire graph down 3 units.");
pq("U3","3.6","Sinusoidal Function Transformations","1",true,"A sinusoidal function has amplitude 5, midline y = 2, and period π. Which equation could represent this function?","f(x) = 5sin(2x) + 2",["f(x) = 2sin(5x) + 5","f(x) = 5sin(x) + 2","f(x) = 5sin(πx) + 2"],"Amplitude 5 and midline y = 2 require the form 5sin(bx) + 2; a period of π requires 2π/b = π, so b = 2, giving f(x) = 5sin(2x) + 2.");

pq("U3","3.7","Sinusoidal Function Context and Data Modeling","1",true,"A location's average daily temperature is modeled by T(t) = 15sin[(π/6)(t − 4)] + 60, where t is months since January (t = 0). What is the period of this model, and what does it represent in context?","12 months, matching the yearly repeat of the seasonal pattern.",["6 months, representing the fact that the temperature pattern repeats twice a year.","15 months, representing the amplitude of the temperature swing.","60 months, representing the average temperature."],"The period is 2π divided by the coefficient of t inside the sine function: 2π/(π/6) = 12, matching the real-world fact that seasonal temperature patterns repeat annually.");
pq("U3","3.7","Sinusoidal Function Context and Data Modeling","1",true,"Using the same model T(t) = 15sin[(π/6)(t − 4)] + 60, what is the predicted temperature at t = 7?","75",["60","45","15"],"T(7) = 15sin[(π/6)(3)] + 60 = 15sin(π/2) + 60 = 15(1) + 60 = 75. This is the model's maximum temperature, since sin reaches its peak value of 1 exactly at π/2.");
pq("U3","3.7","Sinusoidal Function Context and Data Modeling","3",false,"In a sinusoidal model of seasonal temperature, T(t) = A·sin[B(t − C)] + D, what does the value of D represent in context?","The average (midline) temperature around which the seasonal temperature oscillates.",["The maximum temperature reached during the year.","The number of months in the modeled year.","The temperature at the very start of the year, t = 0."],"D is the vertical shift of the sinusoidal function, which places the midline of the oscillation; in a temperature context, this corresponds to the average temperature the actual temperature swings above and below.");

pq("U3","3.8","The Tangent Function","3",false,"What is the period of the tangent function, y = tan(x)?","π",["2π","π/2","4π"],"Unlike sine and cosine, the tangent function completes its full repeating pattern over an interval of π, half the period of sine and cosine.");
pq("U3","3.8","The Tangent Function","3",false,"At which values of x does y = tan(x) have vertical asymptotes?","At π/2 + kπ, for integer k.",["At x = kπ, for any integer k.","Tangent has no vertical asymptotes.","At x = π/4 + kπ, for any integer k."],"Since tan(x) = sin(x)/cos(x), vertical asymptotes occur wherever cos(x) = 0 (and sine is not also zero there), which happens at x = π/2 + kπ for any integer k.");
pq("U3","3.8","The Tangent Function","1",false,"What is the exact value of tan(π/4)?","1",["√2","0","undefined"],"At π/4, sin(π/4) = cos(π/4) = √2/2, so tan(π/4) = sin(π/4)/cos(π/4) = 1. Whenever sine and cosine are equal at an angle, their ratio (the tangent) must equal 1, regardless of what that common value is.");

pq("U3","3.9","Inverse Trigonometric Functions","1",false,"What is the exact value of arcsin(1/2)?","π/6",["π/3","π/2","5π/6"],"arcsin(1/2) asks for the angle in the restricted range [−π/2, π/2] whose sine is 1/2, which is π/6.");
pq("U3","3.9","Inverse Trigonometric Functions","1",false,"What is the exact value of arccos(0)?","π/2",["0","π","−π/2"],"arccos(0) asks for the angle in the restricted range [0, π] whose cosine is 0, which is π/2.");
pq("U3","3.9","Inverse Trigonometric Functions","3",false,"Why must the range of arcsin(x) be restricted to [−π/2, π/2], rather than allowing all angles whose sine equals x?","Because sine isn't one-to-one, so arcsin needs a restricted range.",["Because sine happens to produce values mainly in that interval.","Because angles outside that interval do not have a defined sine value.","Because arcsin is not really the inverse of sine to begin with."],"Since sine repeats the same output values infinitely often, it isn't one-to-one over all reals; restricting the range to [−π/2, π/2], where sine is one-to-one, is what allows arcsin to be defined as a genuine, single-valued inverse function.");

pq("U3","3.10","Trigonometric Equations and Inequalities","1",false,"Solve 2sin(x) = 1 for all solutions in [0, 2π).","x = π/6 and x = 5π/6",["x = π/6 only","x = π/3 and x = 2π/3","x = π/6 and x = 7π/6"],"Dividing by 2 gives sin(x) = 1/2, which occurs at x = π/6 in the first quadrant and at its supplementary reference angle x = π − π/6 = 5π/6 in the second quadrant, where sine is also positive.");
pq("U3","3.10","Trigonometric Equations and Inequalities","3",false,"When solving a trigonometric equation like sin(x) = 0.5 over the interval [0, 2π), why can there be more than one solution even though a calculator's inverse sine function returns only one value?","Because arcsin returns one value; other quadrants can share it.",["Because the equation itself is invalid and has no real solutions.","Because trigonometric equations never have more than one true solution.","Because sin(x) = 0.5 is actually two different equations."],"A calculator's arcsin gives only the principal value within its restricted range, but the original equation asks for every angle in the full interval with that sine value, which generally includes a second angle from the correspondingly signed quadrant.");

pq("U3","3.11","The Secant, Cosecant, and Cotangent Functions","1",false,"What is the exact value of sec(π/3)?","2",["1/2","√3","2/√3"],"Secant is the reciprocal of cosine: sec(π/3) = 1/cos(π/3) = 1/(1/2) = 2. Taking the reciprocal of a fraction less than 1 always produces a value greater than 1, as it does here.");
pq("U3","3.11","The Secant, Cosecant, and Cotangent Functions","1",false,"What is the exact value of csc(π/6)?","2",["1/2","√3","2/√3"],"Cosecant is the reciprocal of sine: csc(π/6) = 1/sin(π/6) = 1/(1/2) = 2. Since sin(π/6) is a relatively small positive fraction, its reciprocal is correspondingly larger than 1.");
pq("U3","3.11","The Secant, Cosecant, and Cotangent Functions","1",false,"What is the exact value of cot(π/4)?","1",["0","√2","undefined"],"Cotangent is the reciprocal of tangent: cot(π/4) = 1/tan(π/4) = 1/1 = 1. Because tan(π/4) equals exactly 1, its reciprocal is also exactly 1, unlike at most other reference angles.");

pq("U3","3.12","Equivalent Representations of Trigonometric Functions","3",false,"Which identity allows sin^2(x) + cos^2(x) to always be rewritten as 1, for any real value of x?","The Pythagorean identity.",["The double-angle identity for sine.","The sum-to-product identity.","The reciprocal identity relating secant and cosine."],"Because (cos x, sin x) is always a point on the unit circle (radius 1), the Pythagorean theorem applied to that point gives cos^2(x) + sin^2(x) = 1 for every real x, regardless of quadrant.");
pq("U3","3.12","Equivalent Representations of Trigonometric Functions","1",false,"Which expression is equivalent to tan(x) using only sine and cosine?","sin(x)/cos(x)",["cos(x)/sin(x)","1/[sin(x)cos(x)]","sin(x) · cos(x)"],"By its standard definition, the tangent of an angle is the ratio of its sine to its cosine, so tan(x) = sin(x)/cos(x) for any x where cos(x) ≠ 0.");

pq("U3","3.13","Trigonometry and Polar Coordinates","1",true,"A point has polar coordinates (r, θ) = (4, π/3). What are its rectangular (x, y) coordinates?","(2, 2√3)",["(2√3, 2)","(4, π/3)","(2, √3)"],"Using x = r·cos(θ) and y = r·sin(θ): x = 4·cos(π/3) = 4(1/2) = 2, and y = 4·sin(π/3) = 4(√3/2) = 2√3.");
pq("U3","3.13","Trigonometry and Polar Coordinates","1",true,"A point has rectangular coordinates (3, 4). What is its polar radius r?","5",["7","√7","12"],"The polar radius is r = √(x^2 + y^2) = √(3^2 + 4^2) = √(9 + 16) = √25 = 5. This is the same distance formula used to find how far a rectangular point sits from the origin.");
pq("U3","3.13","Trigonometry and Polar Coordinates","3",false,"Why can the same point in the plane be represented by more than one pair of polar coordinates?","Because adding 2π to θ, or flipping r's sign, gives the same point.",["Because polar coordinates are inherently ambiguous and cannot reliably describe a unique point.","Because a point in the plane can have several different distances from the origin.","Because r and θ get recalculated using a different formula each time."],"Polar coordinates aren't unique the way rectangular coordinates are: the same physical point is reached again after a full 2π rotation in θ, or by using a negative r paired with an angle rotated by π, so many (r, θ) pairs can name one location.");

pq("U3","3.14","Polar Function Graphs","3",false,"The polar graph of r = 3 (a constant) represents which shape in the plane?","A circle of radius 3 around the origin.",["A single point 3 units from the origin.","A straight line 3 units long.","A spiral that grows outward without bound."],"When r is held constant at 3 while θ varies over all angles, every point traced out is exactly 3 units from the origin in every direction, which traces a circle of radius 3 centered at the origin.");
pq("U3","3.14","Polar Function Graphs","3",false,"The polar graph of θ = π/4 (a constant, with r allowed to vary over all reals) represents which shape?","A full line through the origin at 45°.",["A circle passing through the origin.","A single ray starting at the origin.","A point at angle 45° from the origin."],"Holding θ fixed at π/4 while letting r range over all real numbers (including negative values, which point in the opposite direction) traces out a complete straight line through the origin at that angle, not just one ray.");

pq("U3","3.15","Rates of Change in Polar Functions","3",false,"For a polar function r(θ) that is increasing as θ increases, what does this indicate about the corresponding curve?","The curve is spiraling farther from the origin as the angle increases.",["The curve is a perfect circle centered at the origin.","The curve is approaching the origin as the angle increases.","The rate of change in a polar function has no effect on the shape of the curve."],"Since r directly measures distance from the origin at each angle θ, an increasing r(θ) means the traced curve moves progressively farther from the origin as θ sweeps through increasing angles, producing an outward spiral rather than a closed circle.");
pq("U3","3.15","Rates of Change in Polar Functions","1",true,"For the polar function r(θ) = 2θ, what is the average rate of change of r with respect to θ over the interval [0, π]?","2",["π","2π","1"],"Average rate of change is [r(π) − r(0)]/(π − 0) = (2π − 0)/π = 2, which makes sense since r(θ) = 2θ is itself linear in θ with constant rate 2.");

