// PRECALC_CONTENT_REPAIRS_2026_08_13 — independent clean-room corrections.
function precalcFixItem(id){const q=PRECALC_QUESTIONS.find(x=>x.id===id);if(!q)throw new Error('missing '+id);return q;}
function precalcReplace(id,stem,correct,distractors,explanation){const q=precalcFixItem(id),i=q.c[0],o=distractors.slice();o.splice(i,0,correct);Object.assign(q,{q:stem,o,e:explanation});}
precalcReplace('apprecalc-u1-012','A degree-3 polynomial is increasing on both sides of x = a, has a horizontal tangent at x = a, and changes concavity there. Which feature occurs at x = a?','A stationary point of inflection.',['A vertical asymptote.','A removable discontinuity.','A local maximum.'],'A horizontal tangent alone does not determine the feature, but the stated change in concavity makes x = a an inflection point. Because the function is increasing on both sides, it is not a local maximum or minimum.');
precalcReplace('apprecalc-u1-013','Solve x^2 − 6x + 13 = 0 over the complex numbers.','x = 3 ± 2i',['x = −3 ± 2i','x = 3 ± √13','x = −3 ± √13'],'The quadratic formula gives x = [6 ± √(36 − 52)]/2 = [6 ± 4i]/2 = 3 ± 2i.');
precalcReplace('apprecalc-u1-014','A polynomial with real coefficients has 2 + 3i as a zero. Which quadratic factor with real coefficients must divide the polynomial?','x^2 − 4x + 13',['x^2 + 4x + 13','x^2 − 4x − 13','x^2 + 13'],'The conjugate 2 − 3i is also a zero, and [x − (2 + 3i)][x − (2 − 3i)] = (x − 2)^2 + 9 = x^2 − 4x + 13.');
precalcReplace('apprecalc-u1-015','A degree-3 polynomial with real coefficients has exactly one real zero, x = 5. Which factorization could represent the polynomial?','(x − 5)(x^2 + 4)',['(x − 5)(x^2 − 4)','(x − 5)(x^2 + x − 6)','(x − 5)(x^2 − 6x + 5)'],'The factor x^2 + 4 has only the nonreal conjugate roots ±2i, leaving x = 5 as the only real zero.');
precalcReplace('apprecalc-u1-019','Which expression is equivalent to f(x) = (3x^2 + 1)/(x^2 − 4) and makes the horizontal asymptote easiest to identify?','3 + 13/(x^2 − 4)',['3 − 11/(x^2 − 4)','1 + 5/(x^2 − 4)','3x + 1/(x^2 − 4)'],'Because 3x^2 + 1 = 3(x^2 − 4) + 13, f(x) = 3 + 13/(x^2 − 4). The remainder term tends to 0 as |x| grows, revealing y = 3.');
Object.assign(precalcFixItem('apprecalc-u1-026'),{q:'A rational function has exactly one factor (x − 3) in both its numerator and denominator, and after that factor is canceled the remaining denominator is nonzero at x = 3. What happens at x = 3?',e:'The common factor cancels and the remaining denominator is nonzero at x = 3. The original function is still undefined there, so the discontinuity is removable: a hole rather than a vertical asymptote.'});
precalcReplace('apprecalc-u1-041','A quadratic height model has zeros at t = 0 and t = 6 and reaches a maximum height of 18 at t = 3. Which equation represents the model?','h(t) = −2(t − 3)^2 + 18',['h(t) = 2(t − 3)^2 + 18','h(t) = −2(t + 3)^2 + 18','h(t) = −2(t − 3)^2 + 6'],'The vertex is (3,18), so h(t)=a(t−3)^2+18. Using h(0)=0 gives 9a+18=0, so a=−2; symmetry then also gives the zero t=6.');
Object.assign(precalcFixItem('apprecalc-u2-006'),{q:'A quantity changes from 40 to 65 as x goes from 0 to 5, increasing evenly for a linear model. What is the constant rate of change of this linear model?'});
precalcReplace('apprecalc-u2-007','For f(x) = 3 · 2^x, which statement correctly describes the function as x increases by 1?','The initial value is 3, and each output is twice the preceding output.',['The initial value is 2, and each output increases by 3.','The initial value is 3, and each output increases by 2.','The initial value is 6, and each output is three times the preceding output.'],'Since f(0)=3, the initial value is 3. The base 2 is the multiplicative growth factor, so each one-unit input increase doubles the output.');
precalcReplace('apprecalc-u2-011','For f(x) = 100(1.05)^x, which expression is equivalent and uses x − 2 as the exponent?','110.25(1.05)^(x − 2)',['105(1.05)^(x − 2)','100(1.05)^(x − 2)','110.25(0.05)^(x − 2)'],'Factoring two powers of 1.05 gives 100(1.05)^2(1.05)^(x−2)=110.25(1.05)^(x−2).');
Object.assign(precalcFixItem('apprecalc-u2-012'),{q:'Which expression is equivalent to (4^x)^2 / 4^x?'});
precalcReplace('apprecalc-u2-013','A population is 500 at t = 0 and grows by 3% each year. Which function models the population t years after the baseline?','P(t) = 500(1.03)^t',['P(t) = 500 + 0.03t','P(t) = 500(0.97)^t','P(t) = 503^t'],'A 3% annual increase multiplies the current population by 1.03 each year. With initial value 500, the model is P(t)=500(1.03)^t.');
precalcReplace('apprecalc-u2-020','For f(x) = x^2 and g(x) = x + 1, which expression represents the composition (f ∘ g)(x)?','(x + 1)^2',['x^2 + 1','x^2 + x + 1','2x + 1'],'By definition, (f∘g)(x)=f(g(x)). Substituting g(x)=x+1 into f gives f(x+1)=(x+1)^2.');
precalcReplace('apprecalc-u2-023','If f(x) = 2x + 5, which function g should be constructed so that g(f(x)) = x for every real x?','g(x) = (x − 5)/2',['g(x) = (x + 5)/2','g(x) = 2x − 5','g(x) = 1/(2x + 5)'],'Solving y=2x+5 for x gives x=(y−5)/2, so g(x)=(x−5)/2 and g(f(x))=x.');
precalcReplace('apprecalc-u2-029','Which function g should be constructed as the inverse of f(x) = 5^x?','g(x) = log5(x)',['g(x) = 1/5^x','g(x) = x^5','g(x) = 5log(x)'],'Solving y=5^x for x gives x=log5(y), so the inverse is g(x)=log5(x), with domain x>0.');
precalcReplace('apprecalc-u2-030','Which statement correctly describes f(x) = log10(x)?','It has x-intercept (1, 0) and vertical asymptote x = 0.',['It has x-intercept (0, 1) and horizontal asymptote y = 0.','It has x-intercept (10, 0) and vertical asymptote x = 1.','It has no intercept and no asymptote.'],'Since log10(1)=0, the x-intercept is (1,0). The domain is x>0 and the function tends to −∞ as x approaches 0 from the right, giving vertical asymptote x=0.');
precalcReplace('apprecalc-u2-031','Which statement is true of f(x) = ln(x)?','It is increasing for x > 0, crosses the x-axis at x = 1, and has vertical asymptote x = 0.',['It is decreasing for x > 0 and crosses the y-axis at y = 1.','It is defined for every real x and has horizontal asymptote y = 0.','It is increasing only for x > 1 and is undefined between 0 and 1.'],'The natural logarithm has domain x>0, ln(1)=0, increases throughout its domain, and tends to −∞ as x approaches 0 from the right.');
precalcReplace('apprecalc-u2-032','As x approaches 0 from the positive side, what happens to f(x) = log2(x)?','f(x) decreases without bound toward −∞.',['f(x) approaches 0.','f(x) approaches positive infinity.','f(x) approaches 1.'],'The graph has vertical asymptote x=0. Positive inputs closer to 0 correspond to powers of 2 with exponents that become arbitrarily negative, so log2(x) tends to −∞.');
precalcReplace('apprecalc-u3-023','Solve sin(θ) = 1/2 for θ in the principal arcsine range [−π/2, π/2].','θ = π/6',['θ = π/3','θ = π/2','θ = 5π/6'],'Within the principal arcsine range, π/6 is the unique angle whose sine is 1/2; 5π/6 has the same sine but lies outside the principal range.');
precalcReplace('apprecalc-u3-024','Solve cos(θ) = 0 for θ in the principal arccosine range [0, π].','θ = π/2',['θ = 0','θ = π','θ = −π/2'],'On [0,π], cosine equals 0 only at θ=π/2.');
Object.assign(precalcFixItem('apprecalc-u3-018'),{q:'For T(t) = 15sin[(π/6)(t − 4)] + 60, where t is months since January, what is the predicted temperature at t = 7?'});
precalcReplace('apprecalc-u3-035','Why can the same point in the plane be represented by more than one pair of polar coordinates?','Because (r, θ + 2π) and (−r, θ + π) represent the same point as (r, θ).',['Because changing only the sign of r while keeping θ fixed always gives the same point.','Because a point can have several different distances from the origin.','Because polar coordinates cannot identify a unique location in the plane.'],'Adding a full revolution leaves the point unchanged. Reversing the sign of r must be paired with a π-radian angle change; changing only the sign of r generally gives the opposite point.');
precalcReplace('apprecalc-u3-038','For a polar function r(θ) that is positive and increasing over an interval as θ increases, what does this indicate about the plotted points over that interval?','Their distance from the origin increases as θ increases.',['They remain on one circle centered at the origin.','Their distance from the origin decreases as θ increases.','Their distance from the origin is unrelated to r(θ).'],'For positive r, the radial coordinate is exactly the distance from the origin, so increasing r means the plotted points move farther from the origin over the stated interval.');
precalcReplace('apprecalc-u3-039','For the polar function r(θ) = 2θ, how does the radial coordinate change as θ increases?','It increases at a constant rate of 2 units per radian.',['It increases at a constant rate of π units per radian.','It doubles every radian.','It remains constant at 2.'],'Because r(θ)=2θ is linear in θ, its radial coordinate changes by 2 units for each one-radian increase in θ.');
